  "拖动画格子，也可用键盘逐格上色。保存新的作品：创造力 +3、好奇心 +1。空白或重复作品不消耗灵感。": {
    "zh-CN": "拖动画格子，也可用键盘逐格上色。保存新的作品：创造力 +3、好奇心 +1。空白或重复作品不消耗灵感。",
    "en": "Drag across cells or use the keyboard. A new drawing earns Creativity +3 and Curiosity +1. Blank or duplicate drawings use no inspiration.",
    "ja": "ドラッグやキーボードで色を塗れます。新作の保存で創造力+3、好奇心+1。空白や同じ作品ではひらめきを消費しません。"
  },
  "好奇心、创造力、勇气只涨不掉；换皮肤不重置。新的一天灵感至少补到 3 点，上限 9 点。": {
    "zh-CN": "好奇心、创造力、勇气只涨不掉；换皮肤不重置。新的一天灵感至少补到 3 点，上限 9 点。",
    "en": "Curiosity, Creativity and Courage never decrease, and skins don't reset them. Inspiration refills to at least 3 each day, up to 9.",
    "ja": "好奇心・創造力・勇気は減らず、着せ替えでも維持されます。ひらめきは毎日最低3まで回復、上限は9です。"
  },
  "一次散步、完成一局翻牌或保存新的涂鸦，消耗 1 点灵感并获得成长。每天最多成长 6 次，用完后仍可自由练习和保存作品。": {
    "zh-CN": "一次散步、完成一局翻牌或保存新的涂鸦，消耗 1 点灵感并获得成长。每天最多成长 6 次，用完后仍可自由练习和保存作品。",
    "en": "A walk, card game or new drawing uses 1 inspiration to grow. Up to six growth rewards a day; free play and saving art remain available.",
    "ja": "散歩・カードの完成・新しい絵で、ひらめきを1使って成長します。1日6回まで。その後も自由に遊んで作品を保存できます。"
  },
  "真实专注累计每 15 分钟，好奇心 +1；一次确认记录至少 5 分钟，灵感 +1，每天最多 3 次。玩游戏不增加学习时长，也不发小鱼干。专注计时中请先暂停再玩。": {
    "zh-CN": "真实专注累计每 15 分钟，好奇心 +1；一次确认记录至少 5 分钟，灵感 +1，每天最多 3 次。玩游戏不增加学习时长，也不发小鱼干。专注计时中请先暂停再玩。",
    "en": "Every 15 recorded focus minutes adds Curiosity +1. A confirmed session of at least 5 minutes adds 1 inspiration, up to three times daily. Games earn no study time or fish tokens. Pause focus before playing.",
    "ja": "記録した集中15分で好奇心+1。5分以上の確定した記録でひらめき+1、1日3回まで。ゲームで学習時間や小魚は増えません。遊ぶ前に集中を一時停止してください。"
  },
  "好奇心 20 解锁林间小径；勇气 20 解锁六对翻牌、35 解锁星光天台；创造力 20 解锁两种新画笔。散步每条路线有 3 件收藏。作品册最多 12 张；移除作品会清掉画面，但同一作品的成长领取记录会保留。": {
    "zh-CN": "好奇心 20 解锁林间小径；勇气 20 解锁六对翻牌、35 解锁星光天台；创造力 20 解锁两种新画笔。散步每条路线有 3 件收藏。作品册最多 12 张；移除作品会清掉画面，但同一作品的成长领取记录会保留。",
    "en": "Curiosity 20 unlocks the woodland path. Courage 20 unlocks six card pairs, and 35 the rooftop. Creativity 20 unlocks two colors. Each path has three finds. Keep up to 12 artworks; deleting one doesn't reset its reward history.",
    "ja": "好奇心20で森の小道、勇気20で6組のカード、35で星空の屋上、創造力20で2色が開きます。各散歩道に3つの収集品。作品は12枚まで。削除しても成長の受取記録は残ります。"
  },
